window.__votdWeek && window.__votdWeek({"week":"2029-07-09","reading":"Doctrine and Covenants 76","days":[{"d":"2029-07-09","ref":"D&C 76:1","b":"D&C","c":76,"v":1,"he":"שִׁמְעוּ שָׁמַיִם וְהַאֲזִינִי אָרֶץ וְגִילוּ יוֹשְׁבֶיהָ כִּי יְהוָה הוּא הָאֱלֹהִים וּמִבַּלְעָדָיו אֵין מוֹשִׁיעַ׃","en":"Hear, O ye heavens, and give ear, O earth, and rejoice ye inhabitants thereof, for the Lord is God, and beside him there is no Savior."},{"d":"2029-07-10","ref":"D&C 76:5","b":"D&C","c":76,"v":5,"he":"כִּי כֹה אָמַר יְהוָה אֲנִי יְהוָה רַחוּם וְחַנּוּן לִירֵאַי וְחָפֵץ לְכַבֵּד אֶת־הָעוֹבְדִים אוֹתִי בְּצֶדֶק וּבֶאֱמֶת עַד הַקֵּץ׃","en":"For thus saith the Lord—I, the Lord, am merciful and gracious unto those who fear me, and delight to honor those who serve me in righteousness and in truth unto the end."},{"d":"2029-07-11","ref":"D&C 76:22","b":"D&C","c":76,"v":22,"he":"וְעַתָּה אַחֲרֵי עֵדֻיּוֹת רַבּוֹת אֲשֶׁר נִתְּנוּ עָלָיו זֹאת הָעֵדוּת הָאַחֲרוֹנָה אֲשֶׁר אֲנַחְנוּ מְעִידִים עָלָיו כִּי הוּא חָי׃","en":"And now, after the many testimonies which have been given of him, this is the testimony, last of all, which we give of him: That he lives!"},{"d":"2029-07-12","ref":"D&C 76:24","b":"D&C","c":76,"v":24,"he":"כִּי עַל יָדוֹ וּבְיָדוֹ וּמִמֶּנּוּ הָעוֹלָמוֹת נִבְרָאִים וְיוֹשְׁבֵיהֶם הֵם נוֹלָדִים בָּנִים וּבָנוֹת לֵאלֹהִים׃","en":"That by him, and through him, and of him, the worlds are and were created, and the inhabitants thereof are begotten sons and daughters unto God."},{"d":"2029-07-13","ref":"D&C 76:61","b":"D&C","c":76,"v":61,"he":"לָכֵן אַל יִתְהַלֵּל אִישׁ בְּאָדָם כִּי־אִם יִתְהַלֵּל בֵּאלֹהִים אֲשֶׁר יַכְנִיעַ כׇּל אוֹיֵב תַּחַת רַגְלָיו׃","en":"Wherefore, let no man glory in man, but rather let him glory in God, who shall subdue all enemies under his feet."},{"d":"2029-07-14","ref":"D&C 76:62","b":"D&C","c":76,"v":62,"he":"אֵלֶּה יִשְׁכְּנוּ לִפְנֵי אֱלֹהִים וּמְשִׁיחוֹ לְעוֹלָם וָעֶד׃","en":"These shall dwell in the presence of God and his Christ forever and ever."},{"d":"2029-07-15","ref":"D&C 76:114","b":"D&C","c":76,"v":114,"he":"אַךְ גְּדוֹלִים וְנִפְלָאִים מַעֲשֵׂי יְהוָה וְסוֹדוֹת מַלְכוּתוֹ אֲשֶׁר הֶרְאָנוּ הָעוֹלִים עַל כׇּל תְּבוּנָה בִּכְבוֹד וּבְכֹחַ וּבְמֶמְשָׁלָה׃","en":"But great and marvelous are the works of the Lord, and the mysteries of his kingdom which he showed unto us, which surpass all understanding in glory, and in might, and in dominion;"}]});
